package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.io.*;import java.nio.file.*;import org.json.*;
public class NotebookCheck {
 static int passed;interface Work{void run()throws Exception;}static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);passed++;System.out.println("PASS "+name);}static void fails(Work work,String name)throws Exception{try{work.run();throw new AssertionError(name);}catch(IllegalStateException|IllegalArgumentException|SQLiteException|IOException|JSONException expected){passed++;System.out.println("PASS "+name);}}
 static Context context()throws Exception{return new Context(Files.createTempDirectory("seeky-notebook-").toFile());}static long count(SQLiteDatabase db,String table){try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM "+table,null)){c.moveToFirst();return c.getLong(0);}}
 static void legacy(Context c,String uri,String source){SQLiteDatabase db=new SQLiteDatabase(c.getDatabasePath("seeky-reader.db"));db.execSQL("CREATE TABLE draft(uri TEXT,segment INTEGER,digest TEXT,value TEXT,marks TEXT,PRIMARY KEY(uri,segment,digest))");db.execSQL("CREATE TABLE bookmark(id INTEGER PRIMARY KEY,uri TEXT,segment INTEGER,position INTEGER,label TEXT,created INTEGER)");db.execSQL("INSERT INTO draft VALUES(?,?,?,?,?)",new Object[]{uri,0,ReaderStore.digest(source),source,"[]"});db.execSQL("INSERT INTO bookmark VALUES(1,?,0,1,'Rever',1)",new Object[]{uri});db.execSQL("PRAGMA user_version=1");db.close();}
 public static void main(String[] args)throws Exception{
  Context c=context();String uri="file:///livro.pdf",source="Ação de estudo";legacy(c,uri,source);ReaderStore store=new ReaderStore(c);SQLiteDatabase db=store.getWritableDatabase();File before=new File(c.getFilesDir(),"notebook-recovery/before-reader-v2.json");check(before.isFile(),"v1 to v2 migration writes pre-upgrade snapshot");JSONObject saved=new JSONObject(new String(Files.readAllBytes(before.toPath()),"UTF-8"));check(saved.getJSONObject("tables").getJSONArray("draft").getJSONObject(0).getString("value").equals(source),"migration snapshot contains original notebook text");check(count(db,"draft")==1&&count(db,"bookmark")==1,"migration preserves existing notes and bookmarks");
  StudyText original=store.load(uri,0,source),marked=original.copy();marked.mark(0,4,"note","<script>nota & revisão</script>");store.saveEdit(uri,0,source,original,marked,"Nota",null);StudyText cut=marked.copy();cut.replace(0,4,"");store.saveEdit(uri,0,source,marked,cut,"Cortar","Ação");check(store.clips().get(0)[0].equals("Ação"),"cut stores persistent internal clipboard in same transaction");StudyText undo=store.travel(uri,0,source,cut,false);check(ReaderStore.same(undo,marked),"undo cut restores exact text and annotation ranges");store.close();store=new ReaderStore(c);StudyText after=store.travel(uri,0,source,store.load(uri,0,source),true);check(ReaderStore.same(after,cut),"redo survives helper close and database reopen");
  StudyText back=store.travel(uri,0,source,after,false);StudyText branched=back.copy();branched.replace(branched.text.length(),branched.text.length(),"!");store.saveEdit(uri,0,source,back,branched,"Inserir",null);final ReaderStore current=store;final StudyText expected=branched;fails(()->current.travel(uri,0,source,expected,true),"new edit after undo invalidates redo branch");check(count(store.getReadableDatabase(),"edit_history")==2,"discarded redo does not keep an alternate destructive branch");
  StudyText reset=new StudyText(source);store.saveEdit(uri,0,source,branched,reset,"Repor",null);check(store.load(uri,0,source).marks.isEmpty(),"reset removes marks only after durable commit");StudyText restored=store.travel(uri,0,source,reset,false);check(ReaderStore.same(restored,branched),"undo reset recovers annotations and local text edits");
  db=store.getWritableDatabase();long history=count(db,"edit_history");db.execSQL("CREATE TRIGGER reject_clip BEFORE INSERT ON cut_clip BEGIN SELECT RAISE(ABORT,'simulated full disk');END");StudyText bad=restored.copy();bad.replace(0,1,"");final StudyText fullBefore=restored;fails(()->current.saveEdit(uri,0,source,fullBefore,bad,"Cortar","A"),"failure saving internal clip aborts entire cut");check(ReaderStore.same(current.load(uri,0,source),fullBefore)&&count(db,"edit_history")==history,"failed cut rolls back notebook and history together");db.execSQL("DROP TRIGGER reject_clip");
  StudyText stale=new StudyText("outdated view"),next=stale.copy();next.replace(0,0,"x");fails(()->current.saveEdit(uri,0,source,stale,next,"Stale",null),"stale window cannot overwrite committed notebook");fails(()->current.travel(uri,0,"changed original",new StudyText("changed original"),false),"history is isolated by extracted-source digest");
  StudyText value=current.load(uri,0,source);for(int i=0;i<25;i++){StudyText n=value.copy();n.replace(n.text.length(),n.text.length(),"x");current.saveEdit(uri,0,source,value,n,"Append",null);value=n;}check(count(db,"edit_history")==20,"history retention caps at 20 operations per part");for(int i=0;i<20;i++)value=current.travel(uri,0,source,value,false);final StudyText oldest=value;fails(()->current.travel(uri,0,source,oldest,false),"history boundary is explicit and does not alter current text");
  NotebookBackup.recovery(c,db,"export.json");Context imported=context();try(ReaderStore target=new ReaderStore(imported)){NotebookBackup.Result first=NotebookBackup.restore(imported,target,new File(c.getFilesDir(),"notebook-recovery/export.json"));check(first.added==2,"portable active-notebook backup restores text and bookmark");NotebookBackup.Result twice=NotebookBackup.restore(imported,target,new File(c.getFilesDir(),"notebook-recovery/export.json"));check(twice.added==0&&twice.kept==2,"repeated notebook import is idempotent");StudyText old=target.load(uri,0,source),edited=old.copy();edited.replace(0,0,"MY EDIT ");target.saveEdit(uri,0,source,old,edited,"Local",null);NotebookBackup.restore(imported,target,new File(c.getFilesDir(),"notebook-recovery/export.json"));check(target.load(uri,0,source).text.startsWith("MY EDIT "),"import conflicts preserve the existing local notebook");check(new File(imported.getFilesDir(),"notebook-recovery/before-notebook-import.json").isFile(),"import creates a pre-import local snapshot");}
  JSONObject historical=saved.getJSONObject("tables").getJSONArray("draft").getJSONObject(0);StudyText prior=current.load(uri,0,source);current.restoreSaved(historical);check(current.load(uri,0,source).text.equals(source),"selected pre-migration part can be restored without changing original files");StudyText recovered=current.travel(uri,0,source,current.load(uri,0,source),false);check(ReaderStore.same(recovered,prior),"local recovery itself is undoable");check(new File(c.getFilesDir(),"notebook-recovery/before-part-restore.json").isFile(),"part recovery saves the immediately preceding active notebooks");
  JSONObject malformed=new JSONObject(new String(Files.readAllBytes(new File(c.getFilesDir(),"notebook-recovery/export.json").toPath()),"UTF-8"));malformed.getJSONObject("tables").getJSONArray("draft").getJSONObject(0).put("uri","javascript:alert(1)");File attack=new File(c.getFilesDir(),"invalid.json");Files.write(attack.toPath(),malformed.toString().getBytes("UTF-8"));fails(()->NotebookBackup.restore(c,current,attack),"malformed notebook URI rejected before import writes");check(count(db,"draft")==1,"invalid import leaves notebook count unchanged");
  StringWriter html=new StringWriter();NotebookNotes.export(current,uri,"<unsafe title>",html,true);check(!html.toString().contains("<script>")&&!html.toString().contains("<unsafe title>"),"annotation HTML export escapes title and note content");check(!NotebookNotes.list(current,uri,"note",10).isEmpty(),"document panel finds notes across saved parts");
  StudyText latest=current.load(uri,0,source),addition=latest.copy();addition.replace(addition.text.length(),addition.text.length(),"p");StudyState.fail=true;current.saveEdit(uri,0,source,latest,addition,"Dirty failure",null);StudyState.fail=false;check(current.load(uri,0,source).text.equals(addition.text)&&AppDiagnostics.errors>0,"post-commit backup marker failure cannot undo a durable notebook edit");
  ReaderStore.relocate(c,uri,"file:///renamed.pdf");check(current.load("file:///renamed.pdf",0,source).text.equals(addition.text)&&!current.clips().isEmpty(),"file relocation preserves notebook, cut clips and history");
  String validBackup=new String(Files.readAllBytes(new File(c.getFilesDir(),"notebook-recovery/export.json").toPath()),"UTF-8");for(int i=1;i<=8;i++){File truncated=new File(c.getFilesDir(),"truncated-"+i+".json");Files.write(truncated.toPath(),validBackup.substring(0,Math.max(1,validBackup.length()*i/9)).getBytes("UTF-8"));fails(()->NotebookBackup.restore(c,current,truncated),"truncated import "+i+" is rejected");}check(current.getReadableDatabase()!=null,"malformed archive attempts leave the database usable");
  Context blocked=context();legacy(blocked,uri,source);Files.write(new File(blocked.getFilesDir(),"notebook-recovery").toPath(),new byte[]{1});fails(()->new ReaderStore(blocked).getWritableDatabase(),"failed pre-migration snapshot aborts schema upgrade");SQLiteDatabase legacy=new SQLiteDatabase(blocked.getDatabasePath("seeky-reader.db"));try(Cursor v=legacy.rawQuery("PRAGMA user_version",null)){v.moveToFirst();check(v.getInt(0)==1&&count(legacy,"draft")==1,"failed migration keeps old schema version and notebook records");}legacy.close();current.close();
  System.out.println("PASS "+passed+" actual ReaderStore/NotebookBackup/NotebookNotes checks over host JDBC SQLite; Android lifecycle not simulated");
 }
}